}
.cbf-program-overview {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-600);
}
.cbf-program-overview__copy {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-300);
  max-width: 70ch;
}
.cbf-program-overview__intro {
  color: var(--color-content-default-secondary);
  font-size: 18px;
  line-height: 1.6;
}
.cbf-program-overview__stats {
  list-style: none;
  margin: 0;
  padding: 0;
  --grid-min: 12rem;
}
.cbf-metrics-counters {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-500);
}
.cbf-metrics-counters__head {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
  max-width: 70ch;
}
.cbf-metrics-counters__head h2 {
  margin: 0;
}
.cbf-metrics-counters__lede {
  margin: 0;
  color: var(--color-content-default-secondary);
}
.cbf-metrics-counters__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-md, 0.5rem);
  overflow: hidden;
}
.cbf-metrics-counters__list > li {
  display: flex;
  box-shadow: -1px 0 0 var(--color-border-default-subtle);
}
.cbf-metrics-counters__item {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
  padding: var(--spacing-600) var(--spacing-500);
  color: inherit;
  text-decoration: none;
  transition: background 0.16s ease;
  animation: cbf-counters-rise 0.52s cubic-bezier(0.2, 0.7, 0.2, 1) both;
  animation-delay: calc(var(--i) * 70ms);
}
.cbf-metrics-counters__item:hover {
  background: var(--color-background-brand-subtle);
}
.cbf-metrics-counters__item:focus-visible {
  outline: 2px solid var(--color-background-brand);
  outline-offset: -2px;
}
.cbf-metrics-counters__value {
  font-family: var(--typography-font-family-display, var(--typography-font-family-sans));
  font-size: var(--typography-display-sm-font-size);
  font-weight: var(--typography-font-weight-bold, 700);
  line-height: 1;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  color: var(--color-background-brand);
}
.cbf-metrics-counters__word {
  font-size: var(--typography-title-font-size);
  font-weight: var(--typography-font-weight-semibold);
}
.cbf-metrics-counters__label {
  font-size: var(--typography-body-md-font-size);
  line-height: 1.35;
  color: var(--color-content-default-secondary);
}
.cbf-metrics-counters__cta {
  margin-top: auto;
  padding-top: var(--spacing-300);
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100);
  font-size: var(--typography-label-sm-font-size);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-link, var(--color-background-brand));
}
.cbf-metrics-counters__cta .esa-icon {
  transition: transform 0.16s ease;
}
.cbf-metrics-counters__item:hover .cbf-metrics-counters__cta .esa-icon {
  transform: translate(3px);
}
@media (prefers-reduced-motion: reduce) {
  .cbf-metrics-counters__item {
    animation: none;
  }
}
.cbf-metrics-growth {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-500);
}
.cbf-metrics-growth__head {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
  max-width: 70ch;
}
.cbf-metrics-growth__lede {
  margin: 0;
  color: var(--color-content-default-secondary);
}
.cbf-metrics-growth__frame {
  padding: var(--spacing-400) var(--spacing-600) var(--spacing-600);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-400, 12px);
  background: var(--color-background-elevation-raised);
  min-width: 0;
}
.cbf-metrics-growth__frame > esa-tab-layout {
  display: block;
  max-width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: thin;
}
.cbf-metrics-growth__stage {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400);
  padding-top: var(--spacing-300);
  min-width: 0;
}
.cbf-metrics-growth__stage-head {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--spacing-400);
}
.cbf-metrics-growth__facts {
  display: flex;
  gap: var(--spacing-600);
  margin: 0;
}
.cbf-metrics-growth__facts div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.cbf-metrics-growth__facts dt {
  color: var(--color-content-default-tertiary);
}
.cbf-metrics-growth__facts dd {
  margin: 0;
  font-size: var(--typography-body-lg-font-size);
  font-weight: var(--typography-font-weight-semibold);
  font-variant-numeric: tabular-nums;
}
.cbf-metrics-growth__actions {
  display: flex;
  justify-content: flex-end;
}
@media (max-width: 860px) {
  .cbf-metrics-growth__frame {
    padding: var(--spacing-300) var(--spacing-400) var(--spacing-500);
  }
}
.cbf-metrics-basin {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-500);
}
.cbf-metrics-basin__head {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-end;
  gap: var(--spacing-400);
}
.cbf-metrics-basin__head > esa-button-toggle {
  max-width: 100%;
  overflow-x: auto;
}
.cbf-metrics-basin__intro {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
  max-width: 60ch;
}
.cbf-metrics-basin__lede {
  margin: 0;
  color: var(--color-content-default-secondary);
}
.cbf-metrics-basin__frame {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(16rem, 21rem);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-400, 12px);
  overflow: hidden;
  background: var(--color-background-elevation-raised);
}
.cbf-metrics-basin__map {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-300);
  padding: var(--spacing-600);
  background:
    radial-gradient(120% 90% at 0% 0%, var(--color-background-brand-subtle), transparent 60%),
    var(--color-background-elevation-raised);
  min-width: 0;
}
.cbf-metrics-basin__map svg {
  width: 100%;
  height: auto;
  display: block;
  overflow: visible;
}
.cbf-metrics-basin__state path {
  fill: color-mix(in srgb, var(--cbf-blue-700) calc(var(--share) * 85% + 12%), var(--cbf-blue-50));
  stroke: var(--color-background-elevation-raised);
  stroke-width: 2.5;
  stroke-linejoin: round;
  transition:
    fill 0.42s ease,
    transform 0.2s ease,
    filter 0.2s ease;
  transform-box: fill-box;
  transform-origin: center;
}
.cbf-metrics-basin__state:hover path,
.cbf-metrics-basin__state:focus-visible path {
  filter: brightness(1.12);
}
.cbf-metrics-basin__state:focus-visible {
  outline: none;
}
.cbf-metrics-basin__highlight {
  fill: none;
  stroke: var(--cbf-gold-300);
  stroke-width: 4;
  stroke-linejoin: round;
  pointer-events: none;
}
.cbf-metrics-basin__river {
  fill: none;
  stroke: var(--cbf-blue-200);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  pointer-events: none;
  opacity: 0.9;
}
.cbf-metrics-basin__label {
  pointer-events: none;
}
.cbf-metrics-basin__label text {
  font-family: var(--typography-font-family-display, var(--typography-font-family-sans));
  paint-order: stroke;
  stroke-width: 3px;
  stroke-linejoin: round;
}
.cbf-metrics-basin__label-code {
  font-size: var(--typography-label-sm-font-size);
  font-weight: var(--typography-font-weight-semibold);
  letter-spacing: 0.08em;
  fill: var(--color-content-default-knockout);
  stroke: color-mix(in srgb, var(--cbf-blue-950) 55%, transparent);
}
.cbf-metrics-basin__label-value {
  font-size: var(--typography-title-font-size);
  font-weight: var(--typography-font-weight-bold);
  fill: var(--color-content-default-knockout);
  stroke: color-mix(in srgb, var(--cbf-blue-950) 55%, transparent);
}
.cbf-metrics-basin__legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--spacing-200);
  color: var(--color-content-default-tertiary);
}
.cbf-metrics-basin__ramp {
  width: 7rem;
  height: 8px;
  border-radius: var(--radius-full);
  background: linear-gradient(
    to right,
    color-mix(in srgb, var(--cbf-blue-700) 12%, var(--cbf-blue-50)),
    var(--cbf-blue-700)
  );
}
.cbf-metrics-basin__legend-rivers {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100);
  margin-left: var(--spacing-400);
}
.cbf-metrics-basin__river-key {
  width: 1.5rem;
  height: 3px;
  border-radius: 2px;
  background: var(--cbf-blue-200);
}
.cbf-metrics-basin__panel {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-300);
  padding: var(--spacing-600) var(--spacing-500);
  border-inline-start: 1px solid var(--color-border-default-subtle);
}
.cbf-metrics-basin__panel[hidden] {
  display: none;
}
.cbf-metrics-basin__panel-eyebrow {
  margin: 0;
  color: var(--color-content-default-tertiary);
}
.cbf-metrics-basin__panel-title {
  margin: 0;
  font-family: var(--typography-font-family-display, var(--typography-font-family-sans));
  font-size: var(--typography-heading-lg-font-size);
  font-weight: var(--typography-font-weight-bold, 700);
}
.cbf-metrics-basin__rows {
  margin: 0 0 var(--spacing-200);
  display: flex;
  flex-direction: column;
}
.cbf-metrics-basin__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: var(--spacing-300);
  padding: var(--spacing-300) var(--spacing-200);
  border-bottom: 1px solid var(--color-border-default-subtle);
  border-radius: var(--radius-200, 4px);
  transition: background 0.2s ease;
}
.cbf-metrics-basin__row dt {
  color: var(--color-content-default-secondary);
}
.cbf-metrics-basin__row dd {
  margin: 0;
  text-align: right;
}
.cbf-metrics-basin__row-value {
  font-size: var(--typography-body-lg-font-size);
  font-weight: var(--typography-font-weight-semibold);
  font-variant-numeric: tabular-nums;
}
.cbf-metrics-basin__row.is-current {
  background: var(--color-background-brand-subtle);
}
.cbf-metrics-basin__row.is-current dt {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
@media (max-width: 860px) {
  .cbf-metrics-basin__frame {
    grid-template-columns: minmax(0, 1fr);
  }
}
@media (max-width: 860px) {
  .cbf-metrics-basin__panel {
    border-inline-start: 0;
    border-top: 1px solid var(--color-border-default-subtle);
  }
}
@media (max-width: 860px) {
  .cbf-metrics-basin__map {
    padding: var(--spacing-400);
  }
}
@media (prefers-reduced-motion: reduce) {
  .cbf-metrics-basin__state path {
    transition: none;
  }
}
.cbf-metrics-mosaic {
  display: flex;
