.cbf-cumulative-chart {
  margin: 0;
  position: relative;
}
.cbf-cumulative-chart svg {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.cbf-cumulative-chart__stop-top {
  stop-color: var(--color-background-brand-muted);
  stop-opacity: 0.35;
}
.cbf-cumulative-chart__stop-bottom {
  stop-color: var(--color-background-brand-muted);
  stop-opacity: 0;
}
.cbf-cumulative-chart__grid {
  stroke: var(--color-border-default-subtle);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}
.cbf-cumulative-chart__line {
  fill: none;
  stroke: var(--color-background-brand);
  stroke-width: 2.5;
  stroke-dasharray: 1;
  animation: cbf-cc-draw 1.1s cubic-bezier(0.3, 0.6, 0.2, 1) both;
}
.cbf-cumulative-chart__end {
  fill: var(--cbf-gold-300);
  stroke: var(--color-background-default-knockout);
  stroke-width: 2;
}
.cbf-cumulative-chart__tick {
  font-size: var(--typography-label-sm-font-size);
  fill: var(--color-content-default-tertiary);
  font-family: var(--typography-font-family-sans);
}
.cbf-cumulative-chart__tick.is-compact {
  font-size: var(--typography-title-font-size);
}
.cbf-cumulative-chart__cursor[hidden] {
  display: none;
}
.cbf-cumulative-chart__cursor-line {
  stroke: var(--color-background-default-knockout);
  stroke-dasharray: 3 3;
  vector-effect: non-scaling-stroke;
}
.cbf-cumulative-chart__cursor-dot {
  fill: var(--color-background-elevation-raised);
  stroke: var(--color-background-brand);
  stroke-width: 3;
}
.cbf-cumulative-chart__readout {
  margin-top: var(--spacing-200);
  font-variant-numeric: tabular-nums;
  color: var(--color-content-default-secondary);
}
.cbf-cumulative-chart__readout strong {
  color: var(--color-content-default);
}
.cbf-cumulative-chart__scrub {
  display: block;
  margin-top: var(--spacing-300);
  max-width: 28rem;
}
.cbf-cumulative-chart.is-interactive svg {
  cursor: crosshair;
}
@media (prefers-reduced-motion: reduce) {
  .cbf-cumulative-chart__line {
    animation: none;
  }
}
.esa-collapsible {
  border: var(--border-width-default, 1px) solid var(--color-border-default, #cecece);
  border-radius: var(--radius-md, 0.5rem);
  background: var(--color-background-elevation-raised, #fcfcfc);
}
.esa-collapsible--flush {
  border: none;
  border-radius: 0;
  background: transparent;
}
.esa-collapsible--flush > .esa-collapsible__summary,
.esa-collapsible--flush > .esa-collapsible__body {
  padding-inline: 0;
}
.esa-collapsible__summary {
  display: flex;
  align-items: center;
  gap: var(--spacing-200, 0.5rem);
  padding: var(--spacing-300, 0.75rem) var(--spacing-400, 1rem);
  color: var(--color-content-default, #202020);
  cursor: pointer;
  list-style: none;
}
.esa-collapsible__summary::-webkit-details-marker {
  display: none;
}
.esa-collapsible__summary:after {
  content: "";
  width: 8px;
  height: 8px;
  border-right: 2px solid var(--color-content-default-secondary, #646464);
  border-bottom: 2px solid var(--color-content-default-secondary, #646464);
  transform: rotate(-45deg);
  transition: transform 0.15s ease;
  margin-left: auto;
}
.esa-collapsible[open] > .esa-collapsible__summary:after {
  transform: rotate(45deg);
}
.esa-collapsible__summary .esa-icon {
  flex-shrink: 0;
  color: var(--color-content-default-secondary, #646464);
}
.esa-collapsible__body {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400, 1rem);
  padding: 0 var(--spacing-400, 1rem) var(--spacing-400, 1rem);
}
.stack {
  --gap: var(--spacing-400, 1rem);
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}
.stack[data-split] > [data-split] {
  margin-block-end: auto;
}
.grid {
  --gap: var(--spacing-400, 1rem);
  --grid-min: 16rem;
  display: grid;
  gap: var(--gap);
  grid-template-columns: repeat(auto-fit, minmax(min(var(--grid-min), 100%), 1fr));
}

